using System; using System.Threading.Tasks; using Microsoft.Extensions.DependencyInjection; using AIEduPlatform.Infrastructure.Data; using Microsoft.EntityFrameworkCore; using System.Linq; class Program { static async Task Main() { var services = new ServiceCollection(); services.AddDbContext<AppDbContext>(options => options.UseNpgsql("Host=localhost;Database=aiedu;Username=postgres;Password=admin")); var provider = services.BuildServiceProvider(); var db = provider.GetRequiredService<AppDbContext>(); var courses = await db.Courses.ToListAsync(); foreach(var c in courses) { Console.WriteLine($"Course: {c.Id} - NeedsRebuild: {c.NeedsTagRebuild} - Changes: {c.PendingContentChanges}"); } } }
